const provinces=[
{id:'chengdu',name:'Chengdu',x:15,y:68,owner:'shu',troops:8400,prosperity:68,commander:'Guan Yu',face:'關',command:84,blurb:'A fertile basin ringed by mountains; the heart of the Shu realm.',capital:true,adj:['hanzhong','yizhou']},
{id:'hanzhong',name:'Hanzhong',x:29,y:51,owner:'shu',troops:4200,prosperity:52,commander:'Zhang Fei',face:'張',command:89,blurb:'A rugged mountain pass commanding the road into the central plains.',adj:['chengdu','chang an','yizhou','jingzhou']},
{id:'yizhou',name:'Yizhou',x:14,y:40,owner:'shu',troops:2300,prosperity:57,commander:'Zhao Yun',face:'趙',command:91,blurb:'The western marches, rich in timber, horses, and stubborn defenders.',adj:['chengdu','hanzhong']},
{id:'jingzhou',name:'Jingzhou',x:44,y:59,owner:'neutral',troops:3000,prosperity:63,commander:'Liu Biao',face:'劉',command:64,blurb:'A strategic river province coveted by every power in the south.',adj:['hanzhong','chang an','luoyang','xiakou','wuling']},
{id:'chang an',name:'Chang’an',x:43,y:36,owner:'wei',troops:5700,prosperity:69,commander:'Cao Ren',face:'曹',command:82,blurb:'The old western capital, its walls still scarred by the flight of the emperor.',adj:['hanzhong','jingzhou','luoyang','tianshui']},
{id:'luoyang',name:'Luoyang',x:58,y:31,owner:'wei',troops:7800,prosperity:82,commander:'Cao Cao',face:'曹',command:95,blurb:'The imperial capital. Whoever holds Luoyang may speak in the emperor’s name.',capital:true,adj:['chang an','jingzhou','xuchang','ye']},
{id:'xuchang',name:'Xuchang',x:71,y:38,owner:'wei',troops:6100,prosperity:76,commander:'Xiahou Dun',face:'夏',command:87,blurb:'Cao Cao’s seat of power, where court and army are one.',capital:true,adj:['luoyang','ye','shouchun','xiakou']},
{id:'ye',name:'Ye',x:69,y:19,owner:'wei',troops:4600,prosperity:71,commander:'Yuan Shao',face:'袁',command:86,blurb:'The northern stronghold of the Yuan clan, wealthy and hard to dislodge.',capital:true,adj:['luoyang','xuchang','beihai']},
{id:'beihai',name:'Beihai',x:85,y:16,owner:'neutral',troops:2400,prosperity:61,commander:'Kong Rong',face:'孔',command:60,blurb:'A coastal commandery known for scholars and its stubborn governor.',adj:['ye']},
{id:'shouchun',name:'Shouchun',x:76,y:57,owner:'wu',troops:4900,prosperity:67,commander:'Sun Ce',face:'孫',command:92,blurb:'The northern gate to the Yangtze, contested by warlords of north and south.',adj:['xuchang','xiakou','jianye']},
{id:'xiakou',name:'Xiakou',x:59,y:68,owner:'wu',troops:3700,prosperity:64,commander:'Zhou Yu',face:'周',command:93,blurb:'A river fortress where the Yangtze narrows; the southern fleet is at anchor.',adj:['jingzhou','xuchang','shouchun','jianye','wuling']},
{id:'jianye',name:'Jianye',x:83,y:76,owner:'wu',troops:6400,prosperity:78,commander:'Sun Quan',face:'孫',command:88,blurb:'The Wu court overlooks the river from a city of canals, ships, and ambition.',capital:true,adj:['shouchun','xiakou']},
{id:'wuling',name:'Wuling',x:38,y:81,owner:'neutral',troops:1900,prosperity:46,commander:'Jin Xuan',face:'金',command:54,blurb:'A remote southern frontier, lightly defended and rich in new farmland.',adj:['jingzhou','xiakou']}
];
let state={gold:260,food:180,troops:8400,mandate:42,year:194,season:0,orders:3,selected:'chengdu',turn:1,gameOver:false};
const $=id=>document.getElementById(id);const fmt=n=>Math.floor(n).toLocaleString('en-US');const seasonNames=['SPRING','SUMMER','AUTUMN','WINTER'];
function province(id){return provinces.find(p=>p.id===id)}function owned(){return provinces.filter(p=>p.owner==='shu')}
function render(){
$('gold').textContent=fmt(state.gold);$('food').textContent=fmt(state.food);$('troops').textContent=fmt(state.troops);$('mandate').textContent=`${state.mandate} / 100`;$('mandateBar').style.width=state.mandate+'%';$('orders').textContent=`${state.orders} / 3`;$('year').textContent=state.year;$('seasonLabel').textContent=`${seasonNames[state.season]} · ${state.year} AD`;$('heldCount').textContent=`${owned().length} of 13 provinces`;$('objectiveBar').style.width=Math.min(100,owned().length/13*100)+'%';$('distance').textContent=province('luoyang').owner==='shu'?'Capital secured':'Capital unclaimed';$('provinceCount').textContent=`${owned().length} held · 13 territories`;
renderMap();renderDossier();renderActions();}
function renderMap(){const container=$('regions');container.innerHTML='';const routeGroup=$('routes');routeGroup.innerHTML='';provinces.forEach(p=>p.adj.forEach(id=>{const q=province(id);if(p.id<id){const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',p.x*10);line.setAttribute('y1',p.y*6);line.setAttribute('x2',q.x*10);line.setAttribute('y2',q.y*6);line.setAttribute('class','route');routeGroup.appendChild(line)}}));provinces.forEach(p=>{const el=document.createElement('div');el.className=`region ${p.owner==='shu'?'owned':p.owner} ${state.selected===p.id?'selected':''}`;el.style.left=p.x+'%';el.style.top=p.y+'%';el.innerHTML=`<div class="marker"><span>${p.face[0]}</span></div><div class="name">${p.name}</div><div class="force">${(p.troops/1000).toFixed(1)}k troops</div>`;el.onclick=()=>{state.selected=p.id;render();};container.appendChild(el)})}
function renderDossier(){let p=province(state.selected);$('provinceName').textContent=p.name;$('provinceOwner').textContent=p.owner==='shu'?'Shu · Your territory':`${p.owner==='wei'?'Wei':p.owner==='wu'?'Wu':'Independent'} · ${p.commander}`;$('provinceStatus').textContent=p.owner==='shu'?(p.capital?'CAPITAL':'CONTROLLED'):p.owner==='neutral'?'UNCLAIMED':'HOSTILE';$('provinceBlurb').textContent=p.blurb;$('garrison').textContent=fmt(p.troops);$('prosperity').textContent=p.prosperity;$('commanderFace').textContent=p.face;$('commander').textContent=p.commander;$('commanderRole').textContent=`${p.owner==='shu'?'General':'Governor'} · ${p.command} command`;$('armyNote').textContent=p.owner==='shu'?'Select a friendly province to issue orders.':p.adj.some(id=>province(id).owner==='shu')?'Adjacent to your realm · select an order to campaign.':'Beyond your borders · capture neighboring lands first.';}
function renderActions(){let p=province(state.selected),friendly=p.owner==='shu',adjacent=p.adj.some(id=>province(id).owner==='shu'),canAct=state.orders>0&&!state.gameOver;const recruit=$('recruit'),develop=$('develop'),gather=$('gather'),officer=$('officer');recruit.disabled=!canAct||!friendly||state.gold<120;develop.disabled=!canAct||!friendly||state.gold<80;gather.disabled=!canAct||!friendly;officer.disabled=!canAct||!friendly;document.querySelectorAll('.action-btn').forEach(b=>b.title=!friendly?'Choose a friendly province to issue this order':!canAct?'No orders remaining this season':'');$('endTurn').disabled=state.gameOver;$('orderHint').textContent=`${state.orders} orders remaining`;
}
function log(text){$('log').textContent=text}
function action(fn){if(state.orders<=0||state.gameOver)return;fn();state.orders--;render();}
$('recruit').onclick=()=>action(()=>{let p=province(state.selected);if(p.owner!=='shu'||state.gold<120)return;state.gold-=120;p.troops+=2000;state.troops+=2000;log(`New levies muster at ${p.name}. Two thousand soldiers answer Liu Bei’s call.`);$('advice').textContent='An army marches on its stomach. Keep a reserve of grain for the campaign ahead.'});
$('develop').onclick=()=>action(()=>{let p=province(state.selected);if(p.owner!=='shu'||state.gold<80)return;state.gold-=80;p.prosperity=Math.min(100,p.prosperity+12);state.gold+=Math.round(p.prosperity*.35);state.mandate=Math.min(100,state.mandate+3);log(`Canals and fields flourish in ${p.name}. Prosperity rises, and the people praise your rule.`)});
$('gather').onclick=()=>action(()=>{const p=province(state.selected);if(p.owner!=='shu')return;const harvest=70+Math.round(p.prosperity*1.1);state.food+=harvest;log(`A bountiful harvest yields ${harvest} provisions at ${p.name}. The granaries are replenished.`)});
$('officer').onclick=()=>action(()=>{state.mandate=Math.min(100,state.mandate+8);state.gold+=35;log('Liu Bei hears petitions and rewards loyal service. His reputation grows across the realm.');$('advice').textContent='The people remember a just ruler. The Mandate grows with every act of benevolence.'});
function attack(p){let best=Math.max(...p.adj.map(id=>province(id).owner==='shu'?province(id).troops:0));const army=Math.min(best,Math.floor(state.troops*.72));if(state.food<25){log('The army lacks provisions. Harvest grain before marching.');return}if(army<1200){log('Gather more troops in a neighboring province before attacking.');return}const defender=p.troops;const bonus=state.mandate*.012+(state.food>100?.12:0);const power=army*(.65+Math.random()*.55+bonus);const defense=defender*(.65+Math.random()*.55)+(p.owner==='wei'?.18:0)*defender;
state.food-=25;if(power>defense){const loss=Math.min(Math.floor(army*.32),Math.floor(defender*.45));const gain=Math.max(700,Math.floor(army*.23));p.owner='shu';p.troops=gain;state.troops-=loss;state.mandate=Math.min(100,state.mandate+7);state.gold+=35;log(`Victory at ${p.name}! ${p.commander} yields the province; ${fmt(gain)} soldiers join your cause.`);$('advice').textContent=`A hard-won victory at ${p.name}. Let the army rest and secure supply lines before the next march.`;if(p.id==='luoyang'){endGame(true);return}if(owned().length>=13){endGame(true);return}}else{const loss=Math.floor(army*.42);state.troops=Math.max(0,state.troops-loss);const home=province(p.adj.find(id=>province(id).owner==='shu'));if(home)home.troops=Math.max(500,home.troops-loss);state.mandate=Math.max(0,state.mandate-5);log(`The assault on ${p.name} is repelled. Our forces fall back in disarray; regroup before trying again.`);$('advice').textContent='A setback, not a defeat. Restore the army and attack only with a clear advantage.'}}
$('endTurn').onclick=()=>{if(state.gameOver)return;state.turn++;state.season=(state.season+1)%4;if(state.season===0)state.year++;state.orders=3;let income=owned().reduce((a,p)=>a+Math.round(p.prosperity*.45),0);let harvest=owned().reduce((a,p)=>a+Math.round(p.prosperity*.14),0);state.gold+=income;state.food+=harvest;const upkeep=Math.round(state.troops/950);state.food=Math.max(0,state.food-upkeep);if(state.food===0&&state.troops>0){const desert=Math.min(state.troops,Math.ceil(state.troops*.06));state.troops-=desert;owned().forEach(p=>p.troops=Math.max(300,p.troops-Math.floor(desert/Math.max(1,owned().length))));state.mandate=Math.max(0,state.mandate-4);log(`Famine stalks the army! ${fmt(desert)} soldiers desert for lack of food.`)}else if(state.food>12){state.mandate=Math.min(100,state.mandate+1);log(`A new season dawns. The realm yields ${income} silver and ${harvest} grain; the people prosper.`)}if(state.season===0&&state.turn>1){let enemy=provinces.find(p=>p.owner==='wei'&&p.adj.some(id=>province(id).owner==='shu'));if(enemy&&Math.random()<.3){let target=province(enemy.adj.find(id=>province(id).owner==='shu'));if(target&&enemy.troops>target.troops*1.5){const loss=Math.round(target.troops*.12);target.troops-=loss;state.troops-=loss;log(`Cao Cao’s forces raid ${target.name} in winter, carrying off supplies and ${fmt(loss)} men.`)}}}render()};

$('zoomBtn').onclick=()=>{$('map').classList.toggle('survey');const active=$('map').classList.contains('survey');$('zoomBtn').innerHTML=active?'⊖ &nbsp; Return to map':'⊕ &nbsp; Survey map';$('map').style.backgroundSize=active?'120% 120%':'100% 100%';document.querySelectorAll('.region').forEach(e=>e.style.transform=active?'translate(-50%,-50%) scale(1.12)':'')};
function endGame(win){state.gameOver=true;renderActions();$('modalSeal').textContent=win?'漢':'亂';$('modalTitle').textContent=win?'The Mandate is Yours':'The Han Falls';$('modalText').textContent=win?`Liu Bei enters Luoyang beneath banners of red and gold. The imperial seal is restored, and the realm at last has a ruler who serves its people. You united ${owned().length} provinces in ${state.year} AD.`:'Without grain or soldiers, the Shu court scatters into the mountains. The age of heroes ends—for now.';$('modal').classList.remove('hidden')}
$('modalButton').onclick=()=>{$('modal').classList.add('hidden');if(state.gameOver){state.gameOver=false;state={gold:260,food:180,troops:8400,mandate:42,year:194,season:0,orders:3,selected:'chengdu',turn:1,gameOver:false};provinces.forEach((p,i)=>{const original=[['shu',8400],['shu',4200],['shu',2300],['neutral',3000],['wei',5700],['wei',7800],['wei',6100],['wei',4600],['neutral',2400],['wu',4900],['wu',3700],['wu',6400],['neutral',1900]][i];p.owner=original[0];p.troops=original[1]});$('advice').textContent='Build your strength at Chengdu. Train troops or gather the lords before marching east.';log('The Yellow Turbans have fallen, yet the Han court remains weak. The age of heroes begins.');render()}};
render();
</script></body></html>

