27: function renderMap(){const container=$('regions'),routes=$('routes');container.innerHTML='';routes.innerHTML='';provinces.forEach(p=>p.adj.forEach(id=>{const q=province(id);if(q&&p.id<id){const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',p.x*10);line.setAttribute('y1',p.y*6);line.setAttribute('x2',q.x*10);line.setAttribute('y2',q.y*6);line.setAttribute('class','route');routes.appendChild(line)}}));provinces.forEach(p=>{const el=document.createElement('div');el.className=`region ${p.owner==='shu'?'owned':p.owner} ${state.selected===p.id?'selected':''}`;el.style.left=p.x+'%';el.style.top=p.y+'%';el.innerHTML=`<div class="marker"><span>${p.face[0]}</span></div><div class="name">${p.name}</div><div class="force">${(p.troops/1000).toFixed(1)}k troops</div>`;el.onclick=()=>{state.selected=p.id;render()};container.appendChild(el)})}
28: function renderDossier(){const p=province(state.selected);$('provinceName').textContent=p.name;$('provinceOwner').textContent=p.owner==='shu'?'Shu · Your territory':`${p.owner==='wei'?'Wei':p.owner==='wu'?'Wu':'Independent'} · ${p.commander}`;$('provinceStatus').textContent=p.owner==='shu'?(p.capital?'CAPITAL':'CONTROLLED'):p.owner==='neutral'?'UNCLAIMED':'HOSTILE';$('provinceBlurb').textContent=p.blurb;$('garrison').textContent=fmt(p.troops);$('prosperity').textContent=p.prosperity;$('commanderFace').textContent=p.face;$('commander').textContent=p.commander;$('commanderRole').textContent=`${p.owner==='shu'?'General':'Governor'} · ${p.command} command`;$('armyNote').textContent=p.owner==='shu'?'Select a friendly province to issue orders.':p.adj.some(id=>province(id).owner==='shu')?'Adjacent to your realm · select an order to campaign.':'Beyond your borders · capture neighboring lands first.'}
