34: function attack(p){const neighbors=p.adj.map(id=>province(id)).filter(q=>q&&q.owner==='shu');const strongest=neighbors.sort((a,b)=>b.troops-a.troops)[0];if(!strongest)return;const army=Math.min(strongest.troops,Math.floor(state.troops*.72));if(state.food<25){log('The army lacks provisions. Harvest grain before marching.');return}if(army<1200){log('Gather more troops in a neighboring province before attacking.');return}const defender=p.troops,power=army*(.65+Math.random()*.55+state.mandate*.012+(state.food>100?.12:0)),defense=defender*(.65+Math.random()*.55)+(p.owner==='wei'?.18:0)*defender;state.food-=25;if(power>defense){const loss=Math.min(Math.floor(army*.32),Math.floor(defender*.45)),gain=Math.max(700,Math.floor(army*.23));p.owner='shu';p.troops=gain;state.troops=Math.max(500,state.troops-loss);state.mandate=Math.min(100,state.mandate+7);state.gold+=35;log(`Victory at ${p.name}! ${p.commander} yields the province; ${fmt(gain)} soldiers join your cause.`);$('advice').textContent=`A hard-won victory at ${p.name}. Let the army rest and secure supply lines before the next march.`;if(p.id==='luoyang'||owned().length>=13)endGame(true)}else{const loss=Math.floor(army*.42);state.troops=Math.max(0,state.troops-loss);strongest.troops=Math.max(500,strongest.troops-loss);state.mandate=Math.max(0,state.mandate-5);log(`The assault on ${p.name} is repelled. Our forces fall back in disarray; regroup before trying again.`);$('advice').textContent='A setback, not a defeat. Restore the army and attack only with a clear advantage.'}}
35: $('endTurn').onclick=()=>{if(state.gameOver)return;state.turn++;state.season=(state.season+1)%4;if(state.season===0)state.year++;state.orders=3;const income=owned().reduce((n,p)=>n+Math.round(p.prosperity*.45),0),harvest=owned().reduce((n,p)=>n+Math.round(p.prosperity*.14),0);state.gold+=income;state.food+=harvest;state.food=Math.max(0,state.food-Math.round(state.troops/950));if(!state.food&&state.troops){const desert=Math.min(state.troops,Math.ceil(state.troops*.06));state.troops-=desert;owned().forEach(p=>p.troops=Math.max(300,p.troops-Math.floor(desert/Math.max(1,owned().length))));state.mandate=Math.max(0,state.mandate-4);log(`Famine stalks the army! ${fmt(desert)} soldiers desert for lack of food.`)}else if(state.food>12){state.mandate=Math.min(100,state.mandate+1);log(`A new season dawns. The realm yields ${income} silver and ${harvest} grain; the people prosper.`)}render()};
